def solve(inputs: dict) -> float:
    x = inputs.get('value', inputs.get('x', inputs.get('X', inputs.get('seed'))))
    steps = inputs.get('steps', inputs.get('n', inputs.get('iterations')))
    shifts = inputs.get('shifts')
    if shifts is None:
        shifts = [
            (inputs.get('left1', inputs.get('a', 13)), 'left'),
            (inputs.get('right', inputs.get('b', 9)), 'right'),
            (inputs.get('left2', inputs.get('c', 15)), 'left')
        ]
    normalized = []
    for item in shifts:
        if isinstance(item, dict):
            amount = item.get('shift', item.get('amount'))
            direction = item.get('direction', item.get('dir'))
        else:
            amount, direction = item
        normalized.append((int(amount), str(direction).lower()))
    bits = int(inputs.get('bits', inputs.get('width', 32)))
    mask = (1 << bits) - 1
    x, steps = int(x) & mask, int(steps)
    for _ in range(steps):
        for amount, direction in normalized:
            if direction in ('left', 'l', '<<'):
                x ^= (x << amount) & mask
            else:
                x ^= x >> amount
            x &= mask
    return x

